
const page = await figma.getNodeByIdAsync('943:13210');
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({ family: 'Figtree', style: 'SemiBold' });
await figma.loadFontAsync({ family: 'Figtree', style: 'Regular' });
const photos = ["", "", "", "", "", "", "", "", "", ""];
const names = ['Maya Chen','Jordan Ellis','Sam Okonkwo','Priya Nair','Luis Andrade','Alex Rivera','Dana Whitfield','Kenji Sato','Amara Diallo','Noah Patel'];
const hashes = [];
for (let i = 0; i < photos.length; i++) {
  const img = figma.createImage(figma.base64Decode(photos[i]));
  hashes.push(img.hash);
}
const md = await figma.getNodeByIdAsync('979:124');
const textPrimary = await figma.variables.getVariableByIdAsync('VariableID:2:128');
const docs = await figma.getNodeByIdAsync('943:13211');
const section = figma.createAutoLayout('VERTICAL');
section.name = 'Section · Library photos';
section.itemSpacing = 16;
section.primaryAxisSizingMode = 'AUTO';
section.counterAxisSizingMode = 'FIXED';
section.resize(832, 200);
section.fills = [];
docs.appendChild(section);
section.layoutSizingHorizontal = 'FILL';
const title = figma.createText();
title.fontName = { family: 'Figtree', style: 'SemiBold' };
title.fontSize = 18;
title.lineHeight = { unit: 'PIXELS', value: 24 };
let paint = { type: 'SOLID', visible: true, opacity: 1, blendMode: 'NORMAL', color: { r: 0.06, g: 0.09, b: 0.16 } };
title.fills = [figma.variables.setBoundVariableForPaint(paint, 'color', textPrimary)];
title.characters = 'Library photos';
section.appendChild(title);
const blurb = figma.createText();
blurb.fontName = { family: 'Figtree', style: 'Regular' };
blurb.fontSize = 14;
blurb.lineHeight = { unit: 'PIXELS', value: 18 };
blurb.fills = [figma.variables.setBoundVariableForPaint({ type: 'SOLID', visible: true, opacity: 1, blendMode: 'NORMAL', color: { r: 0.06, g: 0.09, b: 0.16 } }, 'color', textPrimary)];
blurb.characters = 'Copy these Avatar instances for mock members. Content=Image, Size=md. Presence off.';
section.appendChild(blurb);
const grid = figma.createAutoLayout('HORIZONTAL');
grid.name = 'items';
grid.itemSpacing = 16;
grid.layoutWrap = 'WRAP';
grid.counterAxisSpacing = 16;
grid.primaryAxisSizingMode = 'FIXED';
grid.counterAxisSizingMode = 'AUTO';
section.appendChild(grid);
grid.resize(832, 120);
grid.layoutSizingHorizontal = 'FILL';
const created = [];
function setPhoto(slot, hash) {
  const fills = [];
  for (let i = 0; i < slot.fills.length; i++) {
    const f = JSON.parse(JSON.stringify(slot.fills[i]));
    if (f.type === 'IMAGE') { f.imageHash = hash; f.scaleMode = 'FILL'; }
    fills.push(f);
  }
  if (!fills.some(function(f) { return f.type === 'IMAGE'; })) {
    fills.push({ type: 'IMAGE', imageHash: hash, scaleMode: 'FILL', visible: true, opacity: 1 });
  }
  slot.fills = fills;
}
for (let i = 0; i < hashes.length; i++) {
  const cell = figma.createAutoLayout('VERTICAL');
  cell.name = 'cell: ' + names[i];
  cell.itemSpacing = 8;
  cell.primaryAxisSizingMode = 'AUTO';
  cell.counterAxisSizingMode = 'AUTO';
  grid.appendChild(cell);
  const av = md.createInstance();
  av.setProperties({ Size: 'md', Content: 'Image', 'Show presence#979:0': false });
  cell.appendChild(av);
  const slot = av.findOne(function(n) { return n.name === 'Avatar.Image · photo slot'; });
  if (slot) setPhoto(slot, hashes[i]);
  const label = figma.createText();
  label.fontName = { family: 'Figtree', style: 'Regular' };
  label.fontSize = 12;
  label.lineHeight = { unit: 'PIXELS', value: 16 };
  label.fills = [figma.variables.setBoundVariableForPaint({ type: 'SOLID', visible: true, opacity: 1, blendMode: 'NORMAL', color: { r: 0.06, g: 0.09, b: 0.16 } }, 'color', textPrimary)];
  label.characters = names[i];
  cell.appendChild(label);
  created.push(av.id);
}
return { createdNodeIds: [section.id, grid.id].concat(created), hashes: hashes, mutatedNodeIds: [docs.id] };
